arguments.command:
cd /tmp/sv-f8b4e2697874423387c5b572a91d7683 && aarch64-linux-gnu-nm -C libmonosgen-2.0.so.dbg 2>/dev/null | awk '{print $1, $3}' | sort | awk -v addr1="0x2f4b20" -v addr2="0x2f4c84" '
BEGIN { a1=strtonum(addr1); a2=strtonum(addr2) }
{ cur=strtonum("0x"$1); names[cur]=$2 }
END {
  n=asorti(names, sorted, "@ind_num_asc")
  for(i=1;i<=n;i++) {
    s=strtonum(sorted[i])
    if(s<=a1) sym1=names[sorted[i]]" + "sprintf("0x%x",a1-s)
    if(s<=a2) sym2=names[sorted[i]]" + "sprintf("0x%x",a2-s)
  }
  print "0x2f4b20: " sym1
  print "0x2f4c84: " sym2
}' 2>&1 | head -5

